mapper.select:
SELECT c.id, c.school_id, c.grade_id, c.class_name, c.class_code, c.term_id, c.head_teacher_id, c.created_at, c.updated_at FROM class c WHERE c.deleted = 0
AND c.school_id = #{request.schoolId}
AND c.grade_id = #{request.gradeId}
AND c.term_id = #{request.termId}
AND c.class_name LIKE CONCAT('%', #{request.className}, '%')
AND c.head_teacher_id = #{request.headTeacherId}
ORDER BY ${request.orderBy}
ASC
DESC
ORDER BY c.created_at DESC
